window.kbPageData["views/entry/k-892a5acd6ef8dc63"] = {"key":"entry/k-892a5acd6ef8dc63","state":{"route":"entry/k-892a5acd6ef8dc63"},"node":{"id":"k-892a5acd6ef8dc63","mode":"k","title":"十个明确","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["modern"],"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"1.明确中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义制度的最\n大优势是中国共产党领导，中国共产党是最高政治领导力量，全党必须增强“四个意识”、\n坚定“四个自信”、做到“两个维护”；\n◎粉笔拓展\n“四个意识”是指政治意识、大局意识、核心意识、看齐意识；“四个自信”即中国特\n色社会主义…","sources":[{"id":"a0c146865ffe032b","label":"十个明确","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.明确中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义制度的最\n大优势是中国共产党领导，中国共产党是最高政治领导力量，全党必须增强“四个意识”、\n坚定“四个自信”、做到“两个维护”；\n◎粉笔拓展\n“四个意识”是指政治意识、大局意识、核心意识、看齐意识；“四个自信”即中国特\n色社会主义道路自信、理论自信、制度自信、文化自信；“两个维护”是中国共产党的最高\n政治原则和根本政治规矩，是指坚决维护习近平总书记党中央的核心、全党的核心地位，坚\n决维护以习近平同志为核心的党中央权威和集中统一领导。\n2.明确坚持和发展中国特色社会主义，总任务是实现社会主义现代化和中华民族伟大复\n兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成富强民主文明和谐美丽的社\n会主义现代化强国，以中国式现代化推进中华民族伟大复兴；\n3.明确新时代我国社会主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发\n展之间的矛盾，必须坚持以人民为中心的发展思想，发展全过程人民民主，推动人的全面发\n展、全体人民共同富裕取得更为明显的实质性进展；\n4.明确中国特色社会主义事业总体布局是经济建设、政治建设、文化建设、社会建设、\n生态文明建设五位一体，战略布局是全面建设社会主义现代化国家、全面深化改革、全面依\n法治国、全面从严治党四个全面；\n5.明确全面深化改革总目标是完善和发展中国特色社会主义制度、推进国家治理体系和\n治理能力现代化；\n6.明确全面推进依法治国总目标是建设中国特色社会主义法治体系、建设社会主义法治\n国家；\n7.明确必须坚持和完善社会主义基本经济制度，使市场在资源配置中起决定性作用，更\n好发挥政府作用，把握新发展阶段，贯彻创新、协调、绿色、开放、共享的新发展理念，加\n快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，推动高质量发展，统\n筹发展和安全；\n8.明确党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，\n把人民军队建设成为世界一流军队；\n9.明确中国特色大国外交要服务民族复兴、促进人类进步，推动建设新型国际关系，推\n动构建人类命运共同体；\n10.明确全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的政治建\n设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗\n争，落实管党治党政治责任，以伟大自我革命引领伟大社会革命。","source":{"doc":"3ccc56f4000d1642c2d1","first":14,"last":16,"page":14,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-892a5acd6ef8dc63":[]}};
